const logs = context.tryUse(MODULE_LOGS);
const log = logs && context.module
  ? context.own(logs.logger(context.module)) : undefined;
log?.write('info', 'viewer.ready', 'Viewer ready', { views: 1 });
// Capture log once; do not call context.tryUse from runtime callbacks.
log?.write('debug', 'viewer.detail', () => expensiveDiagnosticText());
